-- 세트 372: SQL 조인과 서브쿼리 손연습: LEFT JOIN, 여러 테이블 JOIN, HAVING, 서브쿼리, CASE, VIEW
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_sql_join_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (372, 1, '짝이 없는 행 찾기 (LEFT JOIN ... IS NULL)', '**배경** — 한 테이블에 다 담지 않고 고객·상품·주문처럼 **여러 테이블로 나누고**, 조회할 때 `JOIN` 으로 이어 붙입니다. 이 세트의 문제는 작은 가게 데이터베이스 `shop`(`mariadb shop -e ''쿼리''` 로 접속해 실행)을 씁니다. 문제마다 처음 상태에서 다시 시작합니다.

- `customers`(고객 6명): `id`, `name`, `city`. 고객 `han` 은 주문이 한 건도 없습니다.
- `products`(상품 5개): `id`, `name`, `price`, `category`(stationery·electronics)
- `orders`(주문 10건): `id`, `customer_id`(고객 번호), `product_id`(상품 번호), `qty`

**문제** — `LEFT JOIN` 은 왼쪽 테이블의 행을 모두 남기고, 짝이 없으면 오른쪽 컬럼을 `NULL` 로 채웁니다. 이를 이용해 **주문이 한 건도 없는 고객** 의 `name` 을 조회해 그 출력을 **`/tmp/q1.txt`** 에 저장하세요.', '`customers LEFT JOIN orders ON orders.customer_id = customers.id` 로 이은 뒤, 주문 쪽 컬럼이 `NULL` 인 행만 `WHERE ... IS NULL` 로 고릅니다.', 'mariadb shop -e ''SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL;'' > /tmp/q1.txt
cat /tmp/q1.txt

# 왼쪽(고객)은 모두 남고, 주문이 없는 고객은 o.id 가 NULL 이다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q1.txt ] && [ \\"$(sort /tmp/q1.txt)\\" = \\"$(mariadb shop -e \\"SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q1.txt 가 주문 없는 고객 이름(han)과 같다", "cmd": ["sh", "-c", "[ -s /tmp/q1.txt ] && [ \\"$(sort /tmp/q1.txt)\\" = \\"$(mariadb shop -e \\"SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL\\" | sort)\\" ]"]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB CASE", "url": "https://mariadb.com/kb/en/case-operator/"}, {"title": "MariaDB CREATE VIEW", "url": "https://mariadb.com/kb/en/create-view/"}]'),
  (372, 2, '세 테이블 이어 붙이기 (JOIN 두 번)', '고객 `park` 의 **주문 내역** 을 조회하세요. 고객 이름(`name`), 상품 이름(별칭 `product`), 수량(`qty`) 세 컬럼을 **`/tmp/q2.txt`** 에 저장합니다.', '`orders` 를 기준으로 `JOIN customers` 와 `JOIN products` 를 연이어 붙입니다. 두 테이블에 같은 이름의 컬럼(`name`)이 있으니 `c.name`, `p.name` 처럼 테이블 별칭을 앞에 붙이세요.', 'mariadb shop -e "SELECT c.name, p.name AS product, o.qty FROM orders o JOIN customers c ON c.id = o.customer_id JOIN products p ON p.id = o.product_id WHERE c.name = ''park''" > /tmp/q2.txt
cat /tmp/q2.txt

# orders 에 customers, products 를 각각 JOIN 하고 WHERE 로 고객을 좁힌다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q2.txt ] && [ \\"$(sort /tmp/q2.txt)\\" = \\"$(mariadb shop -e \\"SELECT c.name, p.name AS product, o.qty FROM orders o JOIN customers c ON c.id = o.customer_id JOIN products p ON p.id = o.product_id WHERE c.name = ''park''\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q2.txt 가 park 의 주문 내역(3건)과 같다", "cmd": ["sh", "-c", "[ -s /tmp/q2.txt ] && [ \\"$(sort /tmp/q2.txt)\\" = \\"$(mariadb shop -e \\"SELECT c.name, p.name AS product, o.qty FROM orders o JOIN customers c ON c.id = o.customer_id JOIN products p ON p.id = o.product_id WHERE c.name = ''park''\\" | sort)\\" ]"]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB CASE", "url": "https://mariadb.com/kb/en/case-operator/"}, {"title": "MariaDB CREATE VIEW", "url": "https://mariadb.com/kb/en/create-view/"}]'),
  (372, 3, '그룹을 걸러내기 (HAVING)', '주문을 **2건 이상** 한 고객의 이름(`name`)과 주문 건수(별칭 `cnt`)를 조회해 **`/tmp/q3.txt`** 에 저장하세요.', '`WHERE` 는 그룹으로 묶기 **전** 의 행을 거르고, `HAVING` 은 `GROUP BY` 로 묶은 **뒤** 의 그룹을 거릅니다. 건수 조건은 `HAVING COUNT(*) >= 2` 처럼 씁니다.', 'mariadb shop -e ''SELECT c.name, COUNT(*) AS cnt FROM orders o JOIN customers c ON c.id = o.customer_id GROUP BY c.id, c.name HAVING COUNT(*) >= 2;'' > /tmp/q3.txt
cat /tmp/q3.txt

# 고객별로 묶은 뒤 HAVING 으로 건수 2 이상인 그룹만 남긴다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q3.txt ] && [ \\"$(sort /tmp/q3.txt)\\" = \\"$(mariadb shop -e \\"SELECT c.name, COUNT(*) AS cnt FROM orders o JOIN customers c ON c.id = o.customer_id GROUP BY c.id, c.name HAVING COUNT(*) >= 2\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q3.txt 가 2건 이상 주문한 고객(kim, lee, park, jung)과 같다", "cmd": ["sh", "-c", "[ -s /tmp/q3.txt ] && [ \\"$(sort /tmp/q3.txt)\\" = \\"$(mariadb shop -e \\"SELECT c.name, COUNT(*) AS cnt FROM orders o JOIN customers c ON c.id = o.customer_id GROUP BY c.id, c.name HAVING COUNT(*) >= 2\\" | sort)\\" ]"]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB CASE", "url": "https://mariadb.com/kb/en/case-operator/"}, {"title": "MariaDB CREATE VIEW", "url": "https://mariadb.com/kb/en/create-view/"}]'),
  (372, 4, '평균보다 큰 것 찾기 (서브쿼리)', '`products` 에서 가격이 **전체 상품의 평균 가격보다 비싼** 상품의 `name` 을 조회해 **`/tmp/q4.txt`** 에 저장하세요. 평균 값을 직접 적지 말고 **쿼리 안에서 계산** 하세요.', '괄호로 감싼 `SELECT` 를 다른 쿼리의 조건 안에 넣을 수 있습니다(서브쿼리). `price > (SELECT AVG(price) FROM products)` 처럼요.', 'mariadb shop -e ''SELECT name FROM products WHERE price > (SELECT AVG(price) FROM products);'' > /tmp/q4.txt
cat /tmp/q4.txt

# 서브쿼리가 평균을 먼저 구하고, 바깥 쿼리가 그보다 비싼 행을 고른다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q4.txt ] && [ \\"$(sort /tmp/q4.txt)\\" = \\"$(mariadb shop -e \\"SELECT name FROM products WHERE price > (SELECT AVG(price) FROM products)\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q4.txt 가 평균보다 비싼 상품(monitor)과 같다", "cmd": ["sh", "-c", "[ -s /tmp/q4.txt ] && [ \\"$(sort /tmp/q4.txt)\\" = \\"$(mariadb shop -e \\"SELECT name FROM products WHERE price > (SELECT AVG(price) FROM products)\\" | sort)\\" ]"]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB CASE", "url": "https://mariadb.com/kb/en/case-operator/"}, {"title": "MariaDB CREATE VIEW", "url": "https://mariadb.com/kb/en/create-view/"}]'),
  (372, 5, '목록 안에 있는지로 거르기 (IN 서브쿼리)', '`electronics` 분류 상품을 **한 번이라도 주문한** 고객의 `name` 을 조회해 **`/tmp/q5.txt`** 에 저장하세요. 같은 고객이 두 번 나오면 안 됩니다.', '`WHERE id IN (SELECT ...)` 는 서브쿼리가 돌려준 값 목록 안에 있는 행만 고릅니다. `IN` 은 목록에 몇 번 나오든 한 번만 고르므로 중복이 생기지 않습니다.', 'mariadb shop -e "SELECT name FROM customers WHERE id IN (SELECT o.customer_id FROM orders o JOIN products p ON p.id = o.product_id WHERE p.category = ''electronics'')" > /tmp/q5.txt
cat /tmp/q5.txt

# IN 서브쿼리로 electronics 를 주문한 고객 번호 목록을 만들고 그 안의 고객만 고른다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q5.txt ] && [ \\"$(sort /tmp/q5.txt)\\" = \\"$(mariadb shop -e \\"SELECT name FROM customers WHERE id IN (SELECT o.customer_id FROM orders o JOIN products p ON p.id = o.product_id WHERE p.category = ''electronics'')\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q5.txt 가 electronics 를 주문한 고객(kim, choi, park, jung)과 같다", "cmd": ["sh", "-c", "[ -s /tmp/q5.txt ] && [ \\"$(sort /tmp/q5.txt)\\" = \\"$(mariadb shop -e \\"SELECT name FROM customers WHERE id IN (SELECT o.customer_id FROM orders o JOIN products p ON p.id = o.product_id WHERE p.category = ''electronics'')\\" | sort)\\" ]"]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB CASE", "url": "https://mariadb.com/kb/en/case-operator/"}, {"title": "MariaDB CREATE VIEW", "url": "https://mariadb.com/kb/en/create-view/"}]'),
  (372, 6, '조건에 따라 값 바꿔 보여 주기 (CASE)', '`products` 의 `name` 과 가격대 `grade`(별칭)를 조회해 **`/tmp/q6.txt`** 에 저장하세요. `grade` 는 가격이 **100000 이상이면 `high`**, **10000 이상이면 `mid`**, 나머지는 `low` 입니다.', '`CASE WHEN 조건 THEN 값 WHEN 조건 THEN 값 ELSE 값 END` 은 위에서부터 처음 맞는 조건의 값을 돌려줍니다. 큰 기준부터 적으세요.', 'mariadb shop -e "SELECT name, CASE WHEN price >= 100000 THEN ''high'' WHEN price >= 10000 THEN ''mid'' ELSE ''low'' END AS grade FROM products" > /tmp/q6.txt
cat /tmp/q6.txt

# CASE 는 위에서부터 처음 맞는 WHEN 의 값을 쓰므로 큰 기준부터 적는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q6.txt ] && [ \\"$(sort /tmp/q6.txt)\\" = \\"$(mariadb shop -e \\"SELECT name, CASE WHEN price >= 100000 THEN ''high'' WHEN price >= 10000 THEN ''mid'' ELSE ''low'' END AS grade FROM products\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q6.txt 가 상품별 등급(low, low, mid, mid, high)과 같다", "cmd": ["sh", "-c", "[ -s /tmp/q6.txt ] && [ \\"$(sort /tmp/q6.txt)\\" = \\"$(mariadb shop -e \\"SELECT name, CASE WHEN price >= 100000 THEN ''high'' WHEN price >= 10000 THEN ''mid'' ELSE ''low'' END AS grade FROM products\\" | sort)\\" ]"]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB CASE", "url": "https://mariadb.com/kb/en/case-operator/"}, {"title": "MariaDB CREATE VIEW", "url": "https://mariadb.com/kb/en/create-view/"}]'),
  (372, 7, '계산한 값을 합쳐 순위 매기기', '상품별 **매출**(`price` × `qty` 의 합, 별칭 `revenue`)을 구해 **매출이 큰 상위 3개 상품** 의 `name` 과 `revenue` 를 큰 순서대로 **`/tmp/q7.txt`** 에 저장하세요.', '`SUM(p.price * o.qty)` 처럼 집계 함수 안에서 계산할 수 있습니다. 상품별로 `GROUP BY` 하고 `ORDER BY revenue DESC LIMIT 3` 으로 상위만 남깁니다.', 'mariadb shop -e ''SELECT p.name, SUM(p.price * o.qty) AS revenue FROM orders o JOIN products p ON p.id = o.product_id GROUP BY p.id, p.name ORDER BY revenue DESC LIMIT 3;'' > /tmp/q7.txt
cat /tmp/q7.txt

# JOIN 으로 가격과 수량을 이어 붙이고, 상품별 SUM 을 큰 순서로 3개만', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q7.txt ] && [ \\"$(cat /tmp/q7.txt)\\" = \\"$(mariadb shop -e \\"SELECT p.name, SUM(p.price * o.qty) AS revenue FROM orders o JOIN products p ON p.id = o.product_id GROUP BY p.id, p.name ORDER BY revenue DESC LIMIT 3\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q7.txt 가 매출 상위 3개(monitor 200000, keyboard 80000, mouse 45000)와 같다 (순서까지)", "cmd": ["sh", "-c", "[ -s /tmp/q7.txt ] && [ \\"$(cat /tmp/q7.txt)\\" = \\"$(mariadb shop -e \\"SELECT p.name, SUM(p.price * o.qty) AS revenue FROM orders o JOIN products p ON p.id = o.product_id GROUP BY p.id, p.name ORDER BY revenue DESC LIMIT 3\\")\\" ]"]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB CASE", "url": "https://mariadb.com/kb/en/case-operator/"}, {"title": "MariaDB CREATE VIEW", "url": "https://mariadb.com/kb/en/create-view/"}]'),
  (372, 8, '자주 쓰는 조회를 이름 붙여 저장하기 (VIEW)', '**배경** — **뷰(VIEW)** 는 긴 `SELECT` 에 이름을 붙여 저장해 두고 테이블처럼 다시 조회하는 기능입니다.

**문제** — 주문 내역을 이어 붙인 뷰 **`order_detail`** 을 만드세요. 컬럼은 이 순서로: 주문 번호 `id`, 고객 이름 `customer`, 상품 이름 `product`, 수량 `qty`. 주문 10건이 모두 나와야 합니다.', '`CREATE VIEW 이름 AS SELECT ...;` 입니다. 컬럼 이름은 `AS` 별칭으로 정합니다(`c.name AS customer`).', 'mariadb shop -e "CREATE VIEW order_detail AS SELECT o.id, c.name AS customer, p.name AS product, o.qty FROM orders o JOIN customers c ON c.id = o.customer_id JOIN products p ON p.id = o.product_id;"
mariadb shop -e ''SELECT * FROM order_detail;''

# CREATE VIEW 이름 AS SELECT ... 로 저장하고, 이후에는 테이블처럼 SELECT 한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''order_detail''\\")\\" = \\"id,customer,product,qty\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM order_detail\\")\\" = \\"10\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT CONCAT(customer, ''-'', product) FROM order_detail WHERE id = 4\\")\\" = \\"park-keyboard\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "order_detail 의 컬럼이 id, customer, product, qty 순서다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''order_detail''\\")\\" = \\"id,customer,product,qty\\" ]"]}, {"label": "주문 10건이 모두 나온다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM order_detail\\")\\" = \\"10\\" ]"]}, {"label": "4번 주문은 park 의 keyboard 다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT CONCAT(customer, ''-'', product) FROM order_detail WHERE id = 4\\")\\" = \\"park-keyboard\\" ]"]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB CASE", "url": "https://mariadb.com/kb/en/case-operator/"}, {"title": "MariaDB CREATE VIEW", "url": "https://mariadb.com/kb/en/create-view/"}]'),
  (372, 9, '서로 다른 값의 개수 세기 (COUNT DISTINCT)', '주문을 **한 번이라도 한 고객이 모두 몇 명인지** 세어, 결과(컬럼 이름 `buyers`)를 **`/tmp/q9.txt`** 에 저장하세요. `orders` 에는 같은 고객의 주문이 여러 건 있습니다.', '`COUNT(컬럼)` 은 행 수를 세므로 같은 고객이 여러 번 셉니다. 중복을 빼고 세려면 `COUNT(DISTINCT 컬럼)` 입니다.', 'mariadb shop -e ''SELECT COUNT(DISTINCT customer_id) AS buyers FROM orders;'' > /tmp/q9.txt
cat /tmp/q9.txt

# COUNT(DISTINCT 컬럼) 은 서로 다른 값만 센다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(cat /tmp/q9.txt)\\" = \\"$(printf \\"buyers\\\\n5\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q9.txt 가 buyers 5 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q9.txt)\\" = \\"$(printf \\"buyers\\\\n5\\")\\" ]"]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB CASE", "url": "https://mariadb.com/kb/en/case-operator/"}, {"title": "MariaDB CREATE VIEW", "url": "https://mariadb.com/kb/en/create-view/"}]'),
  (372, 10, 'LEFT JOIN 은 어떻게 동작할까?', '`customers LEFT JOIN orders ON ...` 로 이었을 때, **주문이 없는 고객** 의 행은 결과에서 어떻게 될까요?', '"왼쪽" 테이블이 어느 쪽인지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["짝이 없으니 결과에서 빠진다", "결과에 남고, 주문 쪽 컬럼은 NULL 로 채워진다", "오류가 나서 쿼리가 실패한다", "주문 쪽 컬럼이 0 으로 채워져 남는다"]', 1, '`LEFT JOIN` 은 왼쪽 테이블(고객)의 행을 모두 남기고, 오른쪽(주문)에 짝이 없으면 그쪽 컬럼을 `NULL` 로 채웁니다. 짝이 없는 행이 빠지는 것은 `INNER JOIN`(그냥 `JOIN`)입니다. 이 성질로 "주문이 없는 고객"을 `IS NULL` 로 찾을 수 있습니다.', NULL, NULL, NULL, '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB CASE", "url": "https://mariadb.com/kb/en/case-operator/"}, {"title": "MariaDB CREATE VIEW", "url": "https://mariadb.com/kb/en/create-view/"}]'),
  (372, 11, '그룹을 거르는 절', '고객별 주문 건수가 2건 이상인 그룹만 남기는 쿼리입니다. 빈칸을 채우세요.', '`GROUP BY` 로 묶은 **뒤** 에 그룹을 거르는 절이에요.', NULL, NULL, '[]', 'fill', '["HAVING", "WHERE", "FILTER", "WHEN"]', NULL, '`HAVING` 은 `GROUP BY` 로 묶은 뒤의 그룹을 집계 결과로 거릅니다. `WHERE` 는 묶기 전의 행을 거르는 절이라 `GROUP BY` 뒤에 올 수 없고, 집계 함수도 쓸 수 없습니다. `FILTER`·`WHEN` 은 이 자리에 쓰지 않습니다.', '[0]', 'SELECT customer_id, COUNT(*) FROM orders GROUP BY customer_id {0} COUNT(*) >= 2;', NULL, '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB CASE", "url": "https://mariadb.com/kb/en/case-operator/"}, {"title": "MariaDB CREATE VIEW", "url": "https://mariadb.com/kb/en/create-view/"}]'),
  (372, 12, 'SELECT 문의 절을 쓰는 순서', '여러 절을 쓰는 `SELECT` 문에서 **쓰는 순서** 입니다. 순서에 맞게 놓아 보세요.', '무엇을 → 어디서 → 거르고 → 묶고 → 그룹 거르고 → 정렬 순서예요.', NULL, NULL, '[]', 'order', '["`SELECT 컬럼`", "`FROM 테이블 JOIN ...`", "`WHERE 조건`", "`GROUP BY 컬럼`", "`HAVING 조건`", "`ORDER BY 컬럼 LIMIT 개수`"]', NULL, '쓰는 순서는 `SELECT` → `FROM`(+`JOIN`) → `WHERE` → `GROUP BY` → `HAVING` → `ORDER BY` → `LIMIT` 입니다. 이 순서를 어기면 문법 오류가 납니다.', '[0, 1, 2, 3, 4, 5]', NULL, NULL, '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB CASE", "url": "https://mariadb.com/kb/en/case-operator/"}, {"title": "MariaDB CREATE VIEW", "url": "https://mariadb.com/kb/en/create-view/"}]');
